class ValidationError(Exception):
    pass

def validate_user(username, age):
    if not isinstance(username, str):
        raise ValidationError('用户名必须是字符串')
    if len(username) < 3:
        raise ValidationError('用户名至少 3 个字符')
    if ' ' in username:
        raise ValidationError('用户名不能包含空格')
    if not isinstance(age, int) or isinstance(age, bool) or not (0 <= age <= 150):
        raise ValidationError('年龄不合法')
    return '校验通过'

def check(username, age):
    try:
        return validate_user(username, age)
    except ValidationError as exc:
        return str(exc)

for u, a in [('ab', 18), ('li lei', 18), ('lilei', 200), ('lilei', 18)]:
    print(check(u, a))
